// Flux Files screen texts. Keys are the plugin's own string ids (flxfm_js_strings in includes/admin.php), so
// the plugin and the React screen share one set of translations; the dictionaries are generated by
// plugins/flx-files/tools/gen-react-i18n.sh. A "_1" key is the singular of the same text.
import de from './i18n/de.json';
import es from './i18n/es.json';
import fr from './i18n/fr.json';
import ptBr from './i18n/pt-br.json';
import ja from './i18n/ja.json';
import zh from './i18n/zh.json';
import ar from './i18n/ar.json';
import ru from './i18n/ru.json';
import { normalizeLocale } from '@fluxwp/core';
import en from './i18n/en.json';
import tr from './i18n/tr.json';

const enDict: Record<string, string> = en;
const dicts: Record<string, Record<string, string>> = { en: enDict, tr, de, es, fr, 'pt-br': ptBr, ja, zh, ar, ru };

export type Translate = (key: string, ...args: (string | number)[]) => string;

function fill(text: string, args: (string | number)[]): string {
  let i = 0;
  return text.replace(/%(?:(\d+)\$)?[sd]/g, (_m, pos: string | undefined) => String(args[pos ? Number(pos) - 1 : i++] ?? ''));
}

export function translator(locale: string): Translate {
  const d = dicts[normalizeLocale(locale)] ?? enDict;
  return (key, ...args) => {
    const one = args[0] === 1 ? d[key + '_1'] : undefined;
    return fill(one ?? d[key] ?? enDict[key] ?? key, args);
  };
}
